  1	package com.pousada;
  2	
  3	import com.pousada.api.MessageEndpoints;
  4	import com.pousada.api.ReportEndpoints;
  5	import com.pousada.api.ReservationEndpoints;
  6	import com.pousada.api.RoomEndpoints;
  7	import com.pousada.db.Database;
  8	import io.javalin.Javalin;
  9	import java.sql.SQLException;
 10	
 11	public class Application {
 12	    public static void main(String[] args) {
 13	        try {
 14	            Database.initialize();
 15	
 16	            Javalin app = Javalin.create();
 17	
 18	            RoomEndpoints.register(app);
 19	            ReservationEndpoints.register(app);
 20	            MessageEndpoints.register(app);
 21	            ReportEndpoints.register(app);
 22	
 23	            int port = getPort();
 24	            app.start(port);
 25	            System.out.println("Pousada Maré Alta reservation system running on port " + port);
 26	
 27	        } catch (SQLException e) {
 28	            System.err.println("Failed to initialize database: " + e.getMessage());
 29	            e.printStackTrace();
 30	            System.exit(1);
 31	        }
 32	    }
 33	
 34	    private static int getPort() {
 35	        String portEnv = System.getenv("PORT");
 36	        if (portEnv != null && !portEnv.isEmpty()) {
 37	            try {
 38	                return Integer.parseInt(portEnv);
 39	            } catch (NumberFormatException e) {
 40	                System.err.println("Invalid PORT value, using default 7070");
 41	            }
 42	        }
 43	        return 7070;
 44	    }
 45	}
 46	package com.pousada.api;
 47	
 48	import com.fasterxml.jackson.databind.ObjectMapper;
 49	import com.fasterxml.jackson.databind.node.ObjectNode;
 50	import com.pousada.entity.Reservation;
 51	import com.pousada.service.MessageService;
 52	import com.pousada.service.ReservationService;
 53	import io.javalin.Javalin;
 54	import java.math.BigDecimal;
 55	import java.sql.SQLException;
 56	import java.time.LocalDate;
 57	import java.time.format.DateTimeParseException;
 58	
 59	public class ReservationEndpoints {
 60	    private static final ObjectMapper mapper = new ObjectMapper();
 61	
 62	    public static void register(Javalin app) {
 63	        app.post("/reservations", ctx -> {
 64	            try {
 65	                var body = ctx.bodyAsClass(ObjectNode.class);
 66	
 67	                int roomNumber = getIntField(body, "roomNumber");
 68	                String guestName = getStringField(body, "guestName");
 69	                String guestEmail = getStringField(body, "guestEmail");
 70	                String guestCpf = getStringField(body, "guestCpf");
 71	                String checkInStr = getStringField(body, "checkIn");
 72	                String checkOutStr = getStringField(body, "checkOut");
 73	                int guests = getIntField(body, "guests");
 74	                String ratePlan = getStringField(body, "ratePlan");
 75	                String companyCode = body.has("companyCode") ? body.get("companyCode").asText() : null;
 76	
 77	                if (guestName == null || guestEmail == null || guestCpf == null || ratePlan == null) {
 78	                    throw new IllegalArgumentException("INVALID_REQUEST");
 79	                }
 80	
 81	                LocalDate checkIn = parseDate(checkInStr);
 82	                LocalDate checkOut = parseDate(checkOutStr);
 83	
 84	                var service = new ReservationService();
 85	                var reservation = service.createReservation(roomNumber, guestName, guestEmail, guestCpf,
 86	                    checkIn, checkOut, guests, ratePlan, companyCode);
 87	
 88	                ctx.status(201).json(mapReservationResponse(reservation));
 89	            } catch (IllegalArgumentException e) {
 90	                handleError(ctx, e.getMessage());
 91	            } catch (SQLException e) {
 92	                ctx.status(500).json(createError("DATABASE_ERROR", e.getMessage()));
 93	            } catch (DateTimeParseException e) {
 94	                ctx.status(400).json(createError("INVALID_REQUEST", "Invalid date format"));
 95	            } catch (Exception e) {
 96	                ctx.status(400).json(createError("INVALID_REQUEST", e.getMessage()));
 97	            }
 98	        });
 99	
100	        app.get("/reservations/:id", ctx -> {
101	            try {
102	                int id = Integer.parseInt(ctx.pathParam("id"));
103	                var service = new ReservationService();
104	                var reservation = service.getReservation(id);
105	
106	                if (reservation == null) {
107	                    ctx.status(404).json(createError("RESERVATION_NOT_FOUND", "Reservation not found"));
108	                } else {
109	                    ctx.json(mapReservationResponse(reservation));
110	                }
111	            } catch (SQLException e) {
112	                ctx.status(500).json(createError("DATABASE_ERROR", e.getMessage()));
113	            }
114	        });
115	
116	        app.post("/reservations/:id/confirmation", ctx -> {
117	            try {
118	                int id = Integer.parseInt(ctx.pathParam("id"));
119	                var body = ctx.bodyAsClass(ObjectNode.class);
120	                BigDecimal amountPaid = new BigDecimal(body.get("amountPaid").asText());
121	
122	                var service = new ReservationService();
123	                var reservation = service.confirmReservation(id, amountPaid);
124	                ctx.json(mapReservationResponse(reservation));
125	            } catch (IllegalArgumentException e) {
126	                handleError(ctx, e.getMessage());
127	            } catch (SQLException e) {
128	                ctx.status(500).json(createError("DATABASE_ERROR", e.getMessage()));
129	            } catch (Exception e) {
130	                ctx.status(400).json(createError("INVALID_REQUEST", e.getMessage()));
131	            }
132	        });
133	
134	        app.post("/reservations/:id/cancellation", ctx -> {
135	            try {
136	                int id = Integer.parseInt(ctx.pathParam("id"));
137	                var service = new ReservationService();
138	                var reservation = service.cancelReservation(id);
139	                ctx.json(mapReservationResponse(reservation));
140	            } catch (IllegalArgumentException e) {
141	                handleError(ctx, e.getMessage());
142	            } catch (SQLException e) {
143	                ctx.status(500).json(createError("DATABASE_ERROR", e.getMessage()));
144	            }
145	        });
146	
147	        app.post("/reservations/:id/check-in", ctx -> {
148	            try {
149	                int id = Integer.parseInt(ctx.pathParam("id"));
150	                var service = new ReservationService();
151	                var reservation = service.checkIn(id);
152	                ctx.json(mapReservationResponse(reservation));
153	            } catch (IllegalArgumentException e) {
154	                handleError(ctx, e.getMessage());
155	            } catch (SQLException e) {
156	                ctx.status(500).json(createError("DATABASE_ERROR", e.getMessage()));
157	            }
158	        });
159	
160	        app.post("/reservations/:id/check-out", ctx -> {
161	            try {
162	                int id = Integer.parseInt(ctx.pathParam("id"));
163	                var service = new ReservationService();
164	                var reservation = service.checkOut(id);
165	
166	                var messageService = new MessageService();
167	                String voucher = messageService.generateVoucher(reservation);
168	
169	                ctx.json(createVoucherResponse(reservation, voucher));
170	            } catch (IllegalArgumentException e) {
171	                handleError(ctx, e.getMessage());
172	            } catch (SQLException e) {
173	                ctx.status(500).json(createError("DATABASE_ERROR", e.getMessage()));
174	            }
175	        });
176	
177	        app.get("/reservations/:id/document", ctx -> {
178	            try {
179	                int id = Integer.parseInt(ctx.pathParam("id"));
180	                var service = new ReservationService();
181	                var reservation = service.getReservation(id);
182	
183	                if (reservation == null) {
184	                    ctx.status(404).json(createError("RESERVATION_NOT_FOUND", "Reservation not found"));
185	                    return;
186	                }
187	
188	                if (!reservation.status.equals("CONFIRMED") && !reservation.status.equals("CHECKED_IN") &&
189	                    !reservation.status.equals("CHECKED_OUT")) {
190	                    ctx.status(409).json(createError("OPERATION_NOT_ALLOWED",
191	                        "Document only available for paid reservations"));
192	                    return;
193	                }
194	
195	                var messageService = new MessageService();
196	                String voucher = messageService.generateVoucher(reservation);
197	                ctx.json(createVoucherResponse(reservation, voucher));
198	            } catch (SQLException e) {
199	                ctx.status(500).json(createError("DATABASE_ERROR", e.getMessage()));
200	            }
201	        });
202	    }
203	
204	    private static Object mapReservationResponse(Reservation res) {
205	        var obj = new java.util.LinkedHashMap<>();
206	        obj.put("id", res.id);
207	        obj.put("roomNumber", res.roomNumber);
208	        obj.put("roomType", res.roomType);
209	        obj.put("guestName", res.guestName);
210	        obj.put("guestEmail", res.guestEmail);
211	        obj.put("guestCpf", res.guestCpf);
212	        obj.put("checkIn", res.checkIn.toString());
213	        obj.put("checkOut", res.checkOut.toString());
214	        obj.put("guests", res.guests);
215	        obj.put("ratePlan", res.ratePlan);
216	        obj.put("nights", res.nights);
217	        obj.put("subtotal", Double.parseDouble(String.format("%.2f", res.subtotal)));
218	        obj.put("discount", Double.parseDouble(String.format("%.2f", res.discount)));
219	        obj.put("total", Double.parseDouble(String.format("%.2f", res.total)));
220	        obj.put("status", res.status);
221	        obj.put("amountPaid", Double.parseDouble(String.format("%.2f", res.amountPaid)));
222	        obj.put("refund", res.refund == null ? null : Double.parseDouble(String.format("%.2f", res.refund)));
223	        return obj;
224	    }
225	
226	    private static Object createVoucherResponse(Reservation res, String voucher) {
227	        var obj = new java.util.LinkedHashMap<>();
228	        obj.put("title", "Comprovante de reserva");
229	        obj.put("reservationId", res.id);
230	        obj.put("guestName", res.guestName);
231	        obj.put("guestCpf", res.guestCpf);
232	        obj.put("roomNumber", res.roomNumber);
233	        obj.put("roomType", res.roomType);
234	        obj.put("checkIn", res.checkIn.toString());
235	        obj.put("checkOut", res.checkOut.toString());
236	        obj.put("nights", res.nights);
237	        obj.put("subtotal", Double.parseDouble(String.format("%.2f", res.subtotal)));
238	        obj.put("discount", Double.parseDouble(String.format("%.2f", res.discount)));
239	        obj.put("total", Double.parseDouble(String.format("%.2f", res.total)));
240	        return obj;
241	    }
242	
243	    private static Object createError(String code, String msg) {
244	        return new Object() {
245	            public final String error = code;
246	            public final String message = msg;
247	        };
248	    }
249	
250	    private static void handleError(io.javalin.http.Context ctx, String errorCode) {
251	        String message = switch (errorCode) {
252	            case "ROOM_NOT_FOUND" -> "Room not found";
253	            case "RESERVATION_NOT_FOUND" -> "Reservation not found";
254	            case "ROOM_UNAVAILABLE" -> "Room is unavailable for the selected dates";
255	            case "OPERATION_NOT_ALLOWED" -> "This operation is not allowed for the current reservation state";
256	            case "CAPACITY_EXCEEDED" -> "Too many guests for this room";
257	            case "INVALID_REQUEST" -> "Invalid request";
258	            default -> "An error occurred";
259	        };
260	
261	        int status = switch (errorCode) {
262	            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
263	            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
264	            case "CAPACITY_EXCEEDED" -> 422;
265	            default -> 400;
266	        };
267	
268	        ctx.status(status).json(createError(errorCode, message));
269	    }
270	
271	    private static int getIntField(ObjectNode body, String field) throws IllegalArgumentException {
272	        if (!body.has(field)) {
273	            throw new IllegalArgumentException("INVALID_REQUEST");
274	        }
275	        return body.get(field).asInt();
276	    }
277	
278	    private static String getStringField(ObjectNode body, String field) throws IllegalArgumentException {
279	        if (!body.has(field)) {
280	            throw new IllegalArgumentException("INVALID_REQUEST");
281	        }
282	        return body.get(field).asText();
283	    }
284	
285	    private static LocalDate parseDate(String dateStr) throws DateTimeParseException {
286	        return LocalDate.parse(dateStr);
287	    }
288	}

