295	                    destination VARCHAR(255) NOT NULL,
296	                    subject VARCHAR(255) NOT NULL,
297	                    body TEXT NOT NULL,
298	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
299	                )
300	                """);
301	
302	            initializeRooms();
303	        }
304	    }
305	
306	    private static void initializeRooms() throws SQLException {
307	        try (Connection conn = dataSource.getConnection();
308	             Statement stmt = conn.createStatement()) {
309	
310	            stmt.execute("SELECT COUNT(*) FROM rooms");
