312	            rs.next();
313	            if (rs.getInt(1) == 0) {
314	                stmt.execute("INSERT INTO rooms VALUES (101, 'STANDARD', 2, 249.90)");
315	                stmt.execute("INSERT INTO rooms VALUES (102, 'STANDARD', 2, 249.90)");
316	                stmt.execute("INSERT INTO rooms VALUES (201, 'DELUXE', 3, 389.90)");
317	                stmt.execute("INSERT INTO rooms VALUES (202, 'DELUXE', 3, 389.90)");
318	                stmt.execute("INSERT INTO rooms VALUES (301, 'SUITE', 4, 579.90)");
319	            }
320	        }
321	    }
322	
323	    public static DataSource getDataSource() {
324	        return dataSource;
325	    }
326	
327	    public static Connection getConnection() throws SQLException {
328	        return dataSource.getConnection();
329	    }
330	
331	    public static void close() {
332	        if (dataSource != null) {
333	            dataSource.close();
334	        }
335	    }
336	}

