113	    public String getOccupancyReport(LocalDate date) throws SQLException {
114	        StringBuilder csv = new StringBuilder();
115	        csv.append("room,type,reservation,check_in,check_out\n");
116	
117	        try (Connection conn = Database.getConnection();
118	             Statement stmt = conn.createStatement()) {
119	            String sql = "SELECT r.id, r.room_number, r.check_in, r.check_out, rm.type " +
120	                "FROM reservations r " +
121	                "JOIN rooms rm ON r.room_number = rm.number " +
122	                "WHERE r.status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT') " +
123	                "AND r.check_in <= '" + date + "' " +
124	                "AND r.check_out > '" + date + "' " +
125	                "ORDER BY r.room_number ASC";
126	            var rs = stmt.executeQuery(sql);
127	
128	            int occupiedCount = 0;
129	            while (rs.next()) {
130	                csv.append(rs.getInt("room_number")).append(",");
131	                csv.append(rs.getString("type")).append(",");
132	                csv.append(rs.getInt("id")).append(",");
133	                csv.append(rs.getDate("check_in")).append(",");
134	                csv.append(rs.getDate("check_out")).append("\n");
135	                occupiedCount++;
136	            }
137	
138	            int totalRooms = roomService.getAllRooms().size();
139	            csv.append("total,").append(occupiedCount).append("/").append(totalRooms).append("\n");
140	        }
141	
142	        return csv.toString();
