251	public class DateUtil {
252	    public static boolean isHighSeason(LocalDate date) {
253	        Month month = date.getMonth();
254	        int dayOfMonth = date.getDayOfMonth();
255	
256	        if (month == Month.JULY) {
257	            return true;
258	        }
259	
260	        if (month == Month.DECEMBER) {
261	            return dayOfMonth >= 15;
262	        }
263	
264	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
265	            return true;
266	        }
267	
268	        return false;
269	    }
270	
271	    public static int getNights(LocalDate checkIn, LocalDate checkOut) {
272	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
273	    }
274	
275	    public static boolean isWeekend(LocalDate date) {
276	        return date.getDayOfWeek().getValue() == 5; // Friday
277	    }
278	
279	    public static LocalDate nextSunday(LocalDate friday) {
280	        return friday.plusDays(2);
281	    }
282	}
