288	public class Money {
289	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
290	
291	    public static BigDecimal round(BigDecimal value) {
292	        return value.setScale(2, ROUNDING_MODE);
293	    }
294	
295	    public static BigDecimal round(double value) {
296	        return round(BigDecimal.valueOf(value));
297	    }
298	
299	    public static String format(BigDecimal value) {
300	        return value.setScale(2, ROUNDING_MODE).toString();
301	    }
302	
303	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
304	        return round(a.multiply(b));
305	    }
306	
307	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
308	        return round(a.subtract(b));
309	    }
310	
311	    public static BigDecimal add(BigDecimal a, BigDecimal b) {
312	        return round(a.add(b));
313	    }
314	
315	    public static BigDecimal percent(BigDecimal value, BigDecimal percent) {
316	        return round(value.multiply(percent).divide(BigDecimal.valueOf(100), ROUNDING_MODE));
317	    }
318	
319	    public static BigDecimal percent(BigDecimal value, double percent) {
320	        return percent(value, BigDecimal.valueOf(percent));
321	    }
