131	                csv.append(rs.getString("type")).append(",");
132	                csv.append(rs.getInt("id")).append(",");
133	                csv.append(rs.getDate("check_in")).append(",");
134	                csv.append(rs.getDate("check_out")).append("\n");
135	                occupiedCount++;
136	            }
137	
138	            int totalRooms = roomService.getAllRooms().size();
139	            csv.append("total,").append(occupiedCount).append("/").append(totalRooms).append("\n");
140	        }
141	
142	        return csv.toString();
143	    }
144	
145	    public String getRevenueReport(YearMonth month) throws SQLException {
146	        StringBuilder csv = new StringBuilder();
147	        csv.append("reservation,room,check_in,check_out,status,amount\n");
148	
149	        LocalDate monthStart = month.atDay(1);
150	        LocalDate monthEnd = month.atEndOfMonth();
151	
152	        try (Connection conn = Database.getConnection();
153	             Statement stmt = conn.createStatement()) {
154	            String sql = "SELECT id, room_number, check_in, check_out, status, amount_paid, refund " +
155	                "FROM reservations " +
156	                "WHERE EXTRACT(YEAR FROM check_in) = " + month.getYear() + " " +
157	                "AND EXTRACT(MONTH FROM check_in) = " + month.getMonthValue() + " " +
158	                "AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED') " +
159	                "AND (status != 'CANCELLED' OR amount_paid > 0) " +
160	                "ORDER BY check_in ASC, id ASC";
161	            var rs = stmt.executeQuery(sql);
162	
163	            BigDecimal totalAmount = BigDecimal.ZERO;
164	            while (rs.next()) {
165	                int id = rs.getInt("id");
166	                int room = rs.getInt("room_number");
167	                String checkIn = rs.getDate("check_in").toString();
168	                String checkOut = rs.getDate("check_out").toString();
169	                String status = rs.getString("status");
170	                BigDecimal amountPaid = rs.getBigDecimal("amount_paid");
171	                BigDecimal refund = rs.getBigDecimal("refund");
172	
173	                BigDecimal netAmount = amountPaid;
174	                if (refund != null && refund.signum() > 0) {
175	                    netAmount = netAmount.subtract(refund);
176	                }
177	
178	                csv.append(id).append(",");
179	                csv.append(room).append(",");
180	                csv.append(checkIn).append(",");
181	                csv.append(checkOut).append(",");
182	                csv.append(status).append(",");
183	                csv.append(formatDecimal(netAmount)).append("\n");
184	
185	                totalAmount = totalAmount.add(netAmount);
186	            }
187	
188	            csv.append("total,").append(formatDecimal(totalAmount)).append("\n");
189	        }
190	
191	        return csv.toString();
192	    }
193	
194	    private String formatDecimal(BigDecimal value) {
195	        return String.format("%.2f", value);
196	    }
197	}
