299	    public static String format(BigDecimal value) {
300	        return value.setScale(2, ROUNDING_MODE).toString();
301	    }
302	
303	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
304	        return round(a.multiply(b));
305	    }
306	
307	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
308	        return round(a.subtract(b));
309	    }
