311	    public static BigDecimal add(BigDecimal a, BigDecimal b) {
312	        return round(a.add(b));
313	    }
314	
315	    public static BigDecimal percent(BigDecimal value, BigDecimal percent) {
316	        return round(value.multiply(percent).divide(BigDecimal.valueOf(100), ROUNDING_MODE));
317	    }
